def _portal_data(repo: RepositoryModel) -> dict:
    issues = validate(repo)
    return {
        "config": repo.config,
        "metamodel": {"name": repo.metamodel.get("name"), "version": repo.metamodel.get("version"), "standard": repo.metamodel.get("standard")},
        "metrics": metrics(repo, issues),
        "objects": repo.objects,
        "relationships": repo.relationships,
        "views": repo.views,
        "issues": [i.as_dict() for i in issues],
    }


def render_portal(repo: RepositoryModel, output_dir: str | Path) -> Path:
    output_dir = Path(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)
    data = json.dumps(_portal_data(repo), ensure_ascii=False).replace("</", "<\\/")
    title = f"{repo.config.get('name', 'EA-Ops')} · Interactive Architecture Portal"
    html = HTML_TEMPLATE.replace("__TITLE__", title).replace("__DATA__", data)
    out = output_dir / "index.html"
    out.write_text(html, encoding="utf-8")
    return out
